int numStudentsBehind(Student curr) {
    if (noOneBehind(curr)) {
        return 0;                                  // base case
    } else {
        Student personBehind = curr.getBehind();
        return numStudentsBehind(personBehind) + 1; // recursive case
    }
}

int power(int x, int exp) {
    if (exp == 0) {
        return 1;                           // base case
    } else if (exp % 2 == 1) {
        return x * power(x, exp - 1);       // exp lẻ
    } else {
        int y = power(x, exp / 2);          // exp chẵn
        return y * y;
    }
}
// power(5, 3) = 125, power(2, 10) = 1024

int mystery(int n) {
    if (n < 10) return n;
    int a = n / 10;
    int b = n % 10;
    return mystery(a + b);
}
// mystery(648) -> mystery(72) -> mystery(9) -> 9

bool isPalindrome(const string& s) {
    if (s.length() < 2) return true;         // base case
    if (s[0] != s[s.length() - 1]) return false;
    string middle = s.substr(1, s.length() - 2);
    return isPalindrome(middle);
}

void THN(int n, char from, char to, char temp) {
    if (n > 0) {
        THN(n - 1, from, temp, to);
        move(from, to);
        THN(n - 1, temp, to, from);
    }
}
// THN(3, 'A', 'C', 'B'): 7 lần chuyển, bắt đầu A->C A->B C->B A->C ...

