int mem[1000];
int fibo(int n) {
    if (n <= 2) return 1;
    if (mem[n] != -1) return mem[n];
    int res = fibo(n - 2) + fibo(n - 1);
    mem[n] = res;
    return res;
}
int main() {
    memset(mem, -1, sizeof(mem));
    cout << fibo(10);   // 55
}

