int fact(int n) {                  // vòng lặp
    int k = 0, F = 1;
    while (k < n) F = ++k * F;
    return F;
}
int USCLN(int m, int n) {          // khử đệ quy đuôi
    int temp;
    while (n != 0) {               // !B(X)
        temp = m; m = n; n = temp % n;   // X = f(X)
    }
    return m;                      // D(X)
}
void iter_binary(int m) {          // khử bằng stack
    stack<int> stk;
    while (m > 0) {                // !C(X)
        stk.push(m);               // push(S, X)
        m /= 2;                    // X = f(X)
    }
    while (!stk.empty()) {
        int u = stk.top(); stk.pop();
        cout << u % 2;             // B(X)
    }
}

